INSERT INTO public.products(id,category_id,name,description,price_cents,status,featured,department,storefront,currency,enquiry_only,inquiry_colours)
SELECT x.id,c.id,x.name,'Choose your size and quantity to order this sweatshirt online. Add an optional customisation note for our team. Delivery across Pakistan is Rs. 300.',100000,'published',false,'unisex','hood','PKR',false,jsonb_build_array(jsonb_build_object('color',x.color,'color_hex',x.color_hex))
FROM incoming x JOIN public.categories c ON c.storefront='hood' AND c.slug='hood-sweatshirts'
ON CONFLICT(id) DO NOTHING;
WITH incoming AS (SELECT * FROM jsonb_to_recordset($catalog$[{"id": "c65c7988-60cf-4323-89ee-51e00adeab05", "name": "Sweatshirt — Baby Pink", "color": "Baby Pink", "color_hex": "#f3b8d0", "path": "c65c7988-60cf-4323-89ee-51e00adeab05/sweatshirt.png"}, {"id": "578a5f73-c57a-4c95-a23b-2e4d9009665e", "name": "Sweatshirt — White", "color": "White", "color_hex": "#f4f1eb", "path": "578a5f73-c57a-4c95-a23b-2e4d9009665e/sweatshirt.png"}, {"id": "cd0c3407-65e8-498a-a2e5-cdacdbfa998e", "name": "Sweatshirt — Maroon", "color": "Maroon", "color_hex": "#561b28", "path": "cd0c3407-65e8-498a-a2e5-cdacdbfa998e/sweatshirt.png"}, {"id": "1a80ab36-7f1a-4a5f-8350-c1a9b40c35c9", "name": "Sweatshirt — Black", "color": "Black", "color_hex": "#111111", "path": "1a80ab36-7f1a-4a5f-8350-c1a9b40c35c9/sweatshirt.png"}, {"id": "442e672c-5722-4a18-9d03-ef30949d297e", "name": "Sweatshirt — Royal Blue", "color": "Royal Blue", "color_hex": "#224ca7", "path": "442e672c-5722-4a18-9d03-ef30949d297e/sweatshirt.png"}, {"id": "d70357af-0cbc-4c93-9017-91987f29a603", "name": "Sweatshirt — Light Grey", "color": "Light Grey", "color_hex": "#c4c5cb", "path": "d70357af-0cbc-4c93-9017-91987f29a603/sweatshirt.png"}]$catalog$::jsonb) AS x(id uuid,name text,color text,color_hex text,path text))
